import{_ as a,o,c as s,ag as t}from"./chunks/framework.BKVF-9lJ.js";const g=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":1791840224000}'),n={name:"architecture.md"};function i(d,e,c,r,p,l){return o(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>This page describes how the MFE Forge repository is organised, what each package is responsible for, and how data flows through the CLI. It is written for contributors and for users who want to know what the tool does to their files.</p><h2 id="monorepo-layout" tabindex="-1">Monorepo layout <a class="header-anchor" href="#monorepo-layout" aria-label="Permalink to &quot;Monorepo layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mfe-forge/</span></span>
<span class="line"><span>├── packages/</span></span>
<span class="line"><span>│   ├── cli/          mfe-forge          CLI (bins: mfe-forge, mfe), config, discovery, manifest, templates</span></span>
<span class="line"><span>│   ├── core/         @mfe-forge/core    error boundary, remote loader, remote registry, event bus</span></span>
<span class="line"><span>│   ├── router/       @mfe-forge/router  navigation helpers, route generation, route guards</span></span>
<span class="line"><span>│   ├── store/        @mfe-forge/store   global and scoped Zustand stores, store-to-event-bus sync</span></span>
<span class="line"><span>│   ├── design/       @mfe-forge/design  design tokens and CSS custom properties</span></span>
<span class="line"><span>│   └── testing/      @mfe-forge/testing render helper, remote module mocks, polling, Playwright helpers</span></span>
<span class="line"><span>├── docs/             VitePress site; docs/ai/ holds engineering notes and ADRs</span></span>
<span class="line"><span>├── .agents/          rules and skills for the agent operating contract (AGENTS.md)</span></span>
<span class="line"><span>├── .changeset/       Changesets config (fixed versioning across all six packages)</span></span>
<span class="line"><span>├── .github/workflows ci.yml, release.yml, deploy-docs.yml, audit.yml</span></span>
<span class="line"><span>├── turbo.json        task pipeline (build, test, type-check, check:package)</span></span>
<span class="line"><span>└── package.json      Bun workspaces (packages/*), root scripts</span></span></code></pre></div><p>All packages are TypeScript, ESM-only, built with <code>tsup</code>, tested with Vitest, and released together at one version number.</p><h2 id="package-responsibilities" tabindex="-1">Package responsibilities <a class="header-anchor" href="#package-responsibilities" aria-label="Permalink to &quot;Package responsibilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Responsibility</th><th>Main exports</th></tr></thead><tbody><tr><td><a href="./cli/"><code>mfe-forge</code></a></td><td>Scaffolding, discovery, sync, orchestration and diagnostics</td><td>bins <code>mfe-forge</code> / <code>mfe</code>; library exports <code>defineConfig</code>, <code>loadConfig</code>, <code>runDoctor</code>, <code>CliError</code>, <code>ExitCode</code> and types such as <code>MFEConfig</code></td></tr><tr><td><a href="./packages/core"><code>@mfe-forge/core</code></a></td><td>Resilient remote rendering and in-process messaging</td><td><code>MFErrorBoundary</code>, <code>RemoteLoader</code>, <code>LazyRemote</code>, <code>RemoteRegistry</code>, <code>EventBus</code>, <code>globalEventBus</code>, cache helpers</td></tr><tr><td><a href="./packages/router"><code>@mfe-forge/router</code></a></td><td>Cross-scope navigation on top of React Router 7</td><td><code>useMFENavigation</code>, <code>useRouteSync</code>, <code>generateRoutes</code>, <code>createRouteGuard</code></td></tr><tr><td><a href="./packages/store"><code>@mfe-forge/store</code></a></td><td>Shared and per-MFE state on top of Zustand 5</td><td><code>useGlobalStore</code>, <code>createScopedStore</code>, <code>syncStoreAcrossMFEs</code></td></tr><tr><td><a href="./packages/design"><code>@mfe-forge/design</code></a></td><td>Design tokens</td><td><code>tokens</code>, <code>applyTokens</code></td></tr><tr><td><a href="./packages/testing"><code>@mfe-forge/testing</code></a></td><td>Test utilities for MFEs</td><td><code>renderMFE</code>, <code>mockRemoteModule</code>, <code>waitForRemoteLoad</code>, <code>e2eHelpers</code></td></tr></tbody></table><p>The runtime packages do not depend on each other at install time. They are independent building blocks that the generated templates combine.</p><h2 id="inside-the-cli" tabindex="-1">Inside the CLI <a class="header-anchor" href="#inside-the-cli" aria-label="Permalink to &quot;Inside the CLI&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/cli/src/</span></span>
<span class="line"><span>├── bin/index.ts          Commander program; maps CliError to exit codes</span></span>
<span class="line"><span>├── commands/             one file per command (init, generate, dev, build, test, sync,</span></span>
<span class="line"><span>│                         doctor, config, diagnostics = status/graph/inspect/deps/check/migrate)</span></span>
<span class="line"><span>├── utils/</span></span>
<span class="line"><span>│   ├── config.ts         load + validate mfeforge.config.* (zod), save, get/set by dotted key</span></span>
<span class="line"><span>│   ├── discovery.ts      scan apps/&lt;scope&gt;/&lt;name&gt;/vite.config.ts → RemoteApp[]; find hosts</span></span>
<span class="line"><span>│   ├── manifest.ts       create / write / load / validate mfe-forge.manifest.json</span></span>
<span class="line"><span>│   ├── port.ts           free-port allocation inside dev.portRange</span></span>
<span class="line"><span>│   ├── files.ts          Mustache template copy, JSON update, naming helpers</span></span>
<span class="line"><span>│   ├── package-manager.ts  bun / pnpm / npm command builders</span></span>
<span class="line"><span>│   └── exit.ts           ExitCode and CliError</span></span>
<span class="line"><span>├── templates/            app, host, package, library, design-system, init, ci, docker</span></span>
<span class="line"><span>└── types/index.ts        MFEConfig, ProjectContext, RemoteApp, ProjectManifest</span></span></code></pre></div><h3 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h3><p>Every project command starts the same way:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cwd</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> ├─ loadConfig(cwd) ─────────────── mfeforge.config.ts / .js  (static object evaluation)</span></span>
<span class="line"><span> │                                  └─ fallback: cosmiconfig (.mfeforgerc, .mfeforgerc.json, package.json &quot;mfeforge&quot;)</span></span>
<span class="line"><span> │                                  └─ zod schema → defaults filled, or CliError exit 3</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> ├─ getProjectContext ───────────── { rootDir: cwd, appsDir: cwd/apps, packagesDir: cwd/packages, config, scopes }</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> ├─ discoverApps / discoverHosts ── read apps/*/*/vite.config.ts, regex the port, derive names</span></span>
<span class="line"><span> │</span></span>
<span class="line"><span> └─ command</span></span>
<span class="line"><span>      generate  → copyTemplate (Mustache) → update root package.json scripts → patch host</span></span>
<span class="line"><span>      sync      → replace host remotes block + write declarations.d.ts → writeManifest</span></span>
<span class="line"><span>      dev/build/test → execa(&lt;pm&gt; run &lt;script&gt;) per target</span></span>
<span class="line"><span>      doctor/check/deps/status/graph/inspect/migrate → read-only report (status/migrate write the manifest)</span></span></code></pre></div><h3 id="configuration-loading" tabindex="-1">Configuration loading <a class="header-anchor" href="#configuration-loading" aria-label="Permalink to &quot;Configuration loading&quot;">​</a></h3><p><code>mfeforge.config.ts</code> and <code>mfeforge.config.js</code> are not imported. The loader reads the file as text, strips comments, <code>import</code> statements, simple type annotations, <code>as</code> / <code>satisfies</code> assertions and <code>defineConfig&lt;...&gt;</code> generics, replaces <code>export default</code> with <code>return</code>, and evaluates the result with <code>Function</code>. This keeps the CLI free of a TypeScript compiler, at the cost that the default export must be a self-contained object. A <code>.ts</code> file that fails to evaluate produces a warning and the defaults; a <code>.js</code> file that is not a plain object falls through to cosmiconfig. See <a href="./config">Configuration</a>.</p><h3 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h3><p>Templates are plain directories rendered with Mustache. Every text file is rendered (a <code>.mustache</code> suffix is stripped from the output name); binary files are copied verbatim. The variables available to app and host templates include <code>name</code>, <code>scope</code>, <code>fullName</code>, <code>camelName</code>, <code>pascalName</code>, <code>packageName</code>, <code>port</code>, <code>organization</code> and <code>mfeForgeVersion</code>. When the project contains <code>packages/core</code> (as when generating inside the MFE Forge repository itself), runtime dependencies are written as <code>workspace:*</code> instead of the CLI version.</p><p>The <code>ci</code> and <code>docker</code> template directories ship with the package but no command renders them today; see <a href="./publishing">Publishing</a>.</p><h3 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h3><p><code>build</code>, <code>dev</code> and <code>test</code> throw a <code>CliError</code> that the entry point turns into an exit code:</p><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>success</td></tr><tr><td><code>1</code></td><td>user error: unknown app, bad flag combination, invalid argument</td></tr><tr><td><code>2</code></td><td>a delegated task failed (build, test, dev server) or <code>doctor</code> found a failing check</td></tr><tr><td><code>3</code></td><td>configuration could not be loaded or is invalid</td></tr></tbody></table><p>Some commands set <code>process.exitCode = 1</code> directly: <code>sync --check</code>, <code>check</code>, <code>deps --check</code>, <code>migrate --check</code>, <code>config --validate</code> and <code>inspect</code> with an unknown app. <code>init</code> and <code>generate</code> exit with <code>1</code> on any failure.</p><h2 id="runtime-design" tabindex="-1">Runtime design <a class="header-anchor" href="#runtime-design" aria-label="Permalink to &quot;Runtime design&quot;">​</a></h2><ul><li><strong>Errors stay local.</strong> <code>MFErrorBoundary</code> catches render errors of one remote and shows an accessible fallback (<code>role=&quot;alert&quot;</code>, a heading and a <strong>Try again</strong> button). <code>LazyRemote</code> and <code>RemoteLoader</code> rebuild the lazy import on reset, because a rejected <code>React.lazy</code> stays rejected.</li><li><strong>Bounded caching.</strong> <code>RemoteLoader</code> keeps at most 100 lazy components (<code>MAX_CACHE_SIZE</code>) in an LRU map keyed by <code>remoteName/moduleName</code>.</li><li><strong>In-process messaging.</strong> <code>EventBus</code> is a synchronous, in-memory publish/subscribe with a configurable prefix (<code>mfe:</code> by default, <code>mfe:global:</code> for <code>globalEventBus</code>). It does not use DOM events, so cross-MFE delivery depends on sharing <code>@mfe-forge/core</code> as a federation singleton.</li><li><strong>Registry as metadata.</strong> <code>RemoteRegistry</code> stores remote definitions (<code>name</code>, <code>url</code>, optional <code>environment</code>) and health records. It does not fetch or load anything by itself.</li></ul><h2 id="design-decisions" tabindex="-1">Design decisions <a class="header-anchor" href="#design-decisions" aria-label="Permalink to &quot;Design decisions&quot;">​</a></h2><p>Decisions are recorded as ADRs in <a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/tree/main/docs/ai/decisions" target="_blank" rel="noreferrer"><code>docs/ai/decisions</code></a>:</p><ul><li><a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/blob/main/docs/ai/decisions/0001-manifest-and-config.md" target="_blank" rel="noreferrer">ADR 0001: manifest and config roles</a>. <code>mfeforge.config.*</code> is human-authored policy; <code>mfe-forge.manifest.json</code> is generated topology used by diagnostics and sync. Filesystem scanning is not the only source of truth.</li><li><a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/blob/main/docs/ai/decisions/0002-agent-operating-model.md" target="_blank" rel="noreferrer">ADR 0002: operational agent OS</a>. One canonical contract (<code>AGENTS.md</code>) with thin tool-specific adapters, invariant rules and procedural skills.</li></ul><p>Other conventions that shape the code:</p><ul><li><strong>Convention over configuration.</strong> Hosts are <code>apps/&lt;scope&gt;/host</code>; remotes are any other directory with a <code>vite.config.ts</code>; names and URLs are derived, not configured.</li><li><strong>Fixed versioning.</strong> All six packages move together through Changesets, so a CLI version maps to exactly one runtime version.</li><li><strong>Text-level host patching (temporary).</strong> The host&#39;s <code>remotes</code> block is replaced with a regex. The <a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/blob/main/ROADMAP.md" target="_blank" rel="noreferrer">roadmap</a> replaces this with a Vite plugin that reads remotes from configuration (phase B, with a planned ADR 0003 for a federation adapter interface).</li></ul><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><p>See the maintained list in <a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/blob/main/docs/ai/known-issues.md" target="_blank" rel="noreferrer"><code>docs/ai/known-issues.md</code></a> and the user-facing summary in <a href="./troubleshooting">Troubleshooting</a>.</p>`,31)])])}const m=a(n,[["render",i]]);export{g as __pageData,m as default};
